bounded_host_request.command:
set -eu
docker exec -i gace-createvdobot-videobot-poll-1 node --input-type=module <<'NODE'
import fs from 'node:fs';import pg from 'pg';
const pool=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,database:process.env.VIDEOBOT_DB_NAME,password:fs.readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1});
let m=0;
try{
const rows=(await pool.query("SELECT r.delivery_key,r.topic_id,r.paid_message_id,r.free_message_ids,l.title,l.price_stars,l.seller_user_id,l.paid_video_file_id FROM videobot_post_receipts r JOIN videobot_listings l USING(listing_id) WHERE r.status='sent'")).rows;
const keys=new Set((await pool.query("SELECT DISTINCT delivery_key FROM videobot_stars_ledger WHERE kind='paid' AND delivery_key IS NOT NULL")).rows.map(x=>x.delivery_key));
const kept=rows.filter(x=>keys.has(x.delivery_key));
if(kept.length!==1)process.exitCode=91;
else{
 const keep=kept[0],key=x=>String(x),eq=(a,b)=>key(a)===key(b);
 const dup=rows.filter(x=>x.delivery_key!==keep.delivery_key&&eq(x.topic_id,keep.topic_id)&&eq(x.seller_user_id,keep.seller_user_id)&&x.title===keep.title&&eq(x.price_stars,keep.price_stars)&&x.paid_video_file_id===keep.paid_video_file_id&&!keys.has(x.delivery_key));
 const ids=x=>[x.paid_message_id,...(x.free_message_ids??[])].map(Number);
 const k=ids(keep),d=dup.flatMap(ids);
 if(k.length===3)m|=1;
 if(new Set(k).size===3)m|=2;
 if(d.length===dup.length*3)m|=4;
 if(new Set(d).size===d.length)m|=8;
 if(d.some(x=>k.includes(x)))m|=16;
 if(d.every(x=>Number.isSafeInteger(x)&&x>0))m|=32;
 if(dup.some(x=>k.includes(Number(x.paid_message_id))))m|=64;
 process.exitCode=m;
}
}finally{await pool.end()}
NODE
